package com.tecsup.controller; import com.tecsup.client.CategoriaClient; import com.tecsup.repository.ProductoRepository; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/productos") class ProductoEnriquecidoController { private final ProductoRepository repo; private final CategoriaClient client; ProductoEnriquecidoController(ProductoRepository r,CategoriaClient c){repo=r;client=c;} @GetMapping("/{id}/detalle") Map<String,Object> detalle(@PathVariable Long id){var p=repo.findById(id).orElseThrow(()->new NoSuchElementException("Producto no encontrado")); var m=new LinkedHashMap<String,Object>(); m.put("id",p.getId());m.put("nombre",p.getNombre());m.put("precio",p.getPrecio());m.put("stock",p.getStock());m.put("categoriaId",p.getCategoriaId());m.put("categoria",client.get(p.getCategoriaId()));return m;} }
